public class MainActivity extends Activity {
 static final ExecutorService worker=Executors.newSingleThreadExecutor();static final AtomicBoolean busy=new AtomicBoolean();
 private final Handler ui=new Handler(Looper.getMainLooper());private LinearLayout box;private TextView status;private Spinner model,variant,voice;private TextView modelHint;private JSONArray catalog=new JSONArray();private boolean modelSpinnerReady,manualPack,skipModelSelection;private EditText text,url;private CheckBox streaming;private MediaPlayer replay;
 private ModelManager manager;private File latest;private String catalogSelectionKey="";private JSONArray pendingCatalog;private boolean catalogRefreshing;
 private final ExecutorService catalogWorker=Executors.newSingleThreadExecutor();
 private interface Job {void run()throws Exception;}
 private void message(String s){ui.post(()->{if(status!=null)status.setText(s);});}
 private void button(String name,Job job){Button b=new Button(this);b.setText(name);b.setOnClickListener(v->submit(job,null));box.addView(b);}
 private void submit(Job job,String testId){if(!busy.compareAndSet(false,true)){message("请等待当前任务完成");return;}getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);for(int k=0;k<box.getChildCount();k++)box.getChildAt(k).setEnabled(false);worker.execute(()->{JSONObject result=new JSONObject();try{job.run();result.put("ok",true);}catch(Exception e){String msg=e.getMessage();message(ErrorMessages.display(msg));try{result.put("ok",false).put("error",String.valueOf(msg));}catch(Exception ignored){}}finally{if(testId!=null){try{File d=new File(getFilesDir(),"qa");d.mkdirs();Files.write(new File(d,testId+".json").toPath(),result.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception ignored){}}busy.set(false);ui.post(()->{getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);for(int k=0;k<box.getChildCount();k++)box.getChildAt(k).setEnabled(true);updateModelHint();if(pendingCatalog!=null){JSONArray ready=pendingCatalog;pendingCatalog=null;applyCatalog(ready);}});}});}
 private ArrayAdapter<String> choiceAdapter(List<String> values){return new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values){private View label(View v,int p){if(v instanceof TextView){String id=getItem(p);String label=id.equals("P3")?"轻量版":id.equals("P5")?"标准版":id.equals("female")?"女声1":id.equals("female_2")?"女声2":id.equals("male")?"男声1":id.equals("male_2")?"男声2":id;((TextView)v).setText(label);}return v;}public View getView(int p,View v,ViewGroup parent){return label(super.getView(p,v,parent),p);}public View getDropDownView(int p,View v,ViewGroup parent){return label(super.getDropDownView(p,v,parent),p);}};}
 private Spinner select(String[] values){Spinner s=new Spinner(this);s.setAdapter(choiceAdapter(Arrays.asList(values)));box.addView(s);return s;}
 private EditText input(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);box.addView(e);return e;}
 @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(28,28,28,28);sc.addView(box);setContentView(sc);TextView title=new TextView(this);title.setText("OrTTS "+BuildConfig.VERSION_NAME);title.setTextSize(28);box.addView(title);Button speechButton=new Button(this);speechButton.setText("第三方语音模型 / 语音识别 →");speechButton.setOnClickListener(v->{if(!busy.get())startActivity(new Intent(this,SpeechActivity.class));});box.addView(speechButton);TextView section=new TextView(this);section.setText("OrTTS语音合成\n选择模型和声音，即可离线朗读");section.setTextSize(20);box.addView(section);loadCatalog();String[] modelNames=new String[catalog.length()];for(int n=0;n<modelNames.length;n++)modelNames[n]=OwnModelCatalog.title(catalog.optJSONObject(n));model=select(modelNames);model.setSelection(Math.max(0,Math.min(getPreferences(0).getInt("model_index",defaultModelIndex()),modelNames.length-1)));variant=select(new String[]{"P3","P5"});voice=select(new String[]{"female","female_2","male","male_2"});text=input("输入要朗读的文字","你好，很高兴认识你。");modelHint=new TextView(this);modelHint.setText("P3 轻量版 · P5 原生预测器");box.addView(modelHint);streaming=new CheckBox(this);streaming.setText("边生成边播放");streaming.setChecked(true);box.addView(streaming);manager=new ModelManager(this,this::message);
  button("合成语音",()->synthesize(variant.getSelectedItem().toString(),voice.getSelectedItem().toString(),text.getText().toString(),streaming.isChecked(),null));
  button("播放上一条",()->{if(latest==null)throw new IOException("请先合成语音");ui.post(()->{try{if(replay!=null)replay.release();replay=new MediaPlayer();replay.setDataSource(latest.getPath());replay.prepare();replay.start();}catch(Exception e){message("播放失败："+e.getMessage());}});});
  String address="";try(InputStream in=getAssets().open("defaults.json")){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1)data.write(buffer,0,count);address=new JSONObject(new String(data.toByteArray(),java.nio.charset.StandardCharsets.UTF_8)).getString("manifest_url");}catch(Exception ignored){}
  manualPack=getPreferences(0).getBoolean("manual_pack",false);address=getPreferences(0).getString("manifest_url",address);boolean builtin=address.equals("https://modelscope.cn/models/OrientLuna/OrTTS-Qwen3-LFM-0.6B/resolve/v0.2.0-preview/DOWNLOAD_MANIFEST.json");for(int n=0;n<catalog.length();n++)builtin|=address.equals(catalog.optJSONObject(n).optString("manifest_url"));if(builtin)address=selectedModel().optString("manifest_url");url=input("模型下载清单地址（可修改）",address);url.setSingleLine(false);url.setVisibility(View.GONE);button("更换下载地址",()->ui.post(()->url.setVisibility(url.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE)));
  DownloadSources.addSelector(this,box);
  Button downloadButton=new Button(this);downloadButton.setText("下载 / 检查所选模型");box.addView(downloadButton);downloadButton.setOnClickListener(v->{if(busy.get())return;DownloadNetworkPolicy.confirm(this,allowed->submit(()->DownloadNetworkPolicy.run(allowed,()->{NativeBridge.ensureLoaded();downloadSelected(variant.getSelectedItem().toString());NativeBridge.release();message("模型已准备好\n"+manager.downloadSummary());}),null));});
  button("导入本地权重 ZIP",()->ui.post(()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,100);}));
  try{if(manager.hasBundled())button("准备内置权重",()->{manager.importBundled();NativeBridge.release();message("模型已准备好 · 解码器："+manager.decoderLabel());});}catch(Exception ignored){}
  button("查看版本详情",()->ui.post(()->new AlertDialog.Builder(this).setTitle(OwnModelCatalog.title(selectedModel())).setMessage("模型："+selectedModel().optString("id")+"\n版本："+selectedModel().optString("revision")+"\n解码器："+selectedModel().optString("decoder","liquidcodec")).setPositiveButton("关闭",null).show()));button("释放模型",()->{NativeBridge.release();message("已释放运行内存");});status=new TextView(this);status.setTextIsSelectable(true);box.addView(status);message(manager.current()==null?"首次使用请下载所选模型，或导入本地包。共享文件只下载一次。":"模型已准备好 · 解码器："+manager.decoderLabel());model.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(!modelSpinnerReady){modelSpinnerReady=true;skipModelSelection=false;updateModelHint();return;}if(skipModelSelection){skipModelSelection=false;updateModelHint();return;}if(busy.get())return;String nextKey=OwnModelCatalog.key(selectedModel());if(nextKey.equals(catalogSelectionKey)){updateModelHint();return;}catalogSelectionKey=nextKey;manualPack=false;getPreferences(0).edit().putBoolean("manual_pack",false).putInt("model_index",position).apply();url.setText(selectedModel().optString("manifest_url"));NativeBridge.release();manager.selectInstalled(selectedModel().optString("id"),selectedModel().optString("revision"));updateModelHint();message("所选模型："+selectedModel().optString("name")+" · "+manager.modelLabel());}});updateModelHint();catalogSelectionKey=OwnModelCatalog.key(selectedModel());variant.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){updateModelHint();}});Button refresh=new Button(this);refresh.setText("更新可下载模型");refresh.setOnClickListener(v->refreshOwnCatalog());box.addView(refresh);handleTest(getIntent());launchSpeechQA(getIntent());if(!BuildConfig.DEBUG||(!getIntent().hasExtra("qa_action")&&!getIntent().getBooleanExtra("speech_qa",false))){File cached=new File(getFilesDir(),"own-model-catalog.json");if(System.currentTimeMillis()-cached.lastModified()>6*60*60*1000L)refreshOwnCatalog();}
 }
 private void launchSpeechQA(Intent i){if(BuildConfig.DEBUG&&i.getBooleanExtra("speech_qa",false)){Intent speech=new Intent(this,SpeechActivity.class);speech.putExtras(i);startActivity(speech);}}
 private int defaultModelIndex(){for(int i=0;i<catalog.length();i++)if(catalog.optJSONObject(i).optBoolean("p3_only"))return i;return 0;}
 private void loadCatalog(){try(InputStream in=getAssets().open("defaults.json")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);catalog=new JSONObject(new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("models");catalog=OwnModelCatalog.merge(catalog,OwnModelCatalog.cached(new File(getFilesDir(),"own-model-catalog.json")));if(catalog.length()==0)throw new IOException("empty model catalog");}catch(Exception e){throw new IllegalStateException("模型目录不可用",e);}}
 private void updateChoices(Spinner spinner,JSONArray values){ArrayList<String> names=new ArrayList<>();for(int i=0;i<values.length();i++)names.add(values.optString(i));boolean same=spinner.getCount()==names.size();for(int i=0;same&&i<names.size();i++)same=names.get(i).equals(spinner.getItemAtPosition(i));if(same||names.isEmpty())return;String selected=String.valueOf(spinner.getSelectedItem());spinner.setAdapter(choiceAdapter(names));int index=names.indexOf(selected);spinner.setSelection(Math.max(0,index));}
 private void applyCatalog(JSONArray values){if(busy.get()){pendingCatalog=values;return;}String keep=OwnModelCatalog.key(selectedModel());catalog=OwnModelCatalog.merge(catalog,values);ArrayList<String> names=new ArrayList<>();int index=0;for(int i=0;i<catalog.length();i++){JSONObject m=catalog.optJSONObject(i);names.add(OwnModelCatalog.title(m));if(OwnModelCatalog.key(m).equals(keep))index=i;}skipModelSelection=true;model.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));model.setSelection(index);catalogSelectionKey=OwnModelCatalog.key(selectedModel());updateModelHint();}
 private void refreshOwnCatalog(){if(catalogRefreshing)return;catalogRefreshing=true;JSONArray before=catalog;message("正在从ModelScope发现自研模型，仅获取目录…");catalogWorker.execute(()->{try{File cache=new File(getFilesDir(),"own-model-catalog.json");JSONArray found=OwnModelCatalog.refresh(OwnModelCatalog.merge(before,OwnModelCatalog.cached(cache)));OwnModelCatalog.save(cache,found);ui.post(()->{if(isDestroyed())return;applyCatalog(found);if(!busy.get())message("自研模型目录已更新 · "+found.length()+"项，选择后再下载权重");});}catch(Exception e){if(!busy.get())message("目录更新失败，保留离线列表："+e.getMessage());}finally{ui.post(()->catalogRefreshing=false);}});}
 private JSONObject selectedModel(){return catalog.optJSONObject(model==null?0:model.getSelectedItemPosition());}
 private boolean usesBuiltin(){return !manualPack&&url.getText().toString().trim().equals(selectedModel().optString("manifest_url"));}
 private void ensureSelected(){if(usesBuiltin()&&!manager.matchesCurrent(selectedModel().optString("id"),selectedModel().optString("revision"))){NativeBridge.release();manager.selectInstalled(selectedModel().optString("id"),selectedModel().optString("revision"));}}
 private void syncImportedModel(){try{JSONObject imported=ModelManager.manifest(manager.current());String id=imported.getString("model_id"),revision=imported.getString("revision");for(int n=0;n<catalog.length();n++)if(id.equals(catalog.getJSONObject(n).getString("id"))&&revision.equals(catalog.getJSONObject(n).getString("revision"))){final int index=n;getPreferences(0).edit().putInt("model_index",index).putString("manifest_url",catalog.getJSONObject(index).getString("manifest_url")).apply();ui.post(()->{if(model.getSelectedItemPosition()!=index){skipModelSelection=true;model.setSelection(index);}url.setText(catalog.optJSONObject(index).optString("manifest_url"));updateModelHint();});return;}ui.post(this::updateModelHint);}catch(Exception ignored){}}
 private JSONObject builtinForUrl(String address){for(int n=0;n<catalog.length();n++){JSONObject e=catalog.optJSONObject(n);if(address.equals(e.optString("manifest_url")))return e;}return null;}
 private File downloadSelected(String v)throws Exception{JSONObject entry=builtinForUrl(url.getText().toString().trim());File root=manager.download(url.getText().toString().trim(),v,entry);manualPack=entry==null;getPreferences(0).edit().putBoolean("manual_pack",manualPack).apply();if(manualPack)syncImportedModel();else ui.post(this::updateModelHint);return root;}
 private void updateModelHint(){if(busy.get())return;if(manualPack){String hint="本地导入模型";try{JSONObject meta=ModelManager.manifest(manager.current());if(meta.has("research_policy"))hint+="\n精简版 · 仅提供轻量版";}catch(Exception ignored){}modelHint.setText(hint);return;}JSONObject e=selectedModel();JSONArray variants=e.optJSONArray("supported_variants"),presets=e.optJSONArray("voices");if(variants==null)variants=new JSONArray(Arrays.asList("P3","P5"));if(presets==null)presets=new JSONArray(Arrays.asList("female","female_2","male","male_2"));updateChoices(variant,variants);updateChoices(voice,presets);long size=e.optLong(String.valueOf(variant.getSelectedItem())+"_bytes");modelHint.setText(OwnModelCatalog.title(e)+(size>0?String.format(Locale.ROOT," · 完整文件约 %.2f GB",size/1e9):"")+"\n轻量版 P3 需加装小预测器；标准版 P5 使用原生预测器。主模型共用。\n相同文件自动复用，实际下载量会减少"+(e.optBoolean("p3_only")?"\n仅提供轻量版":""));}

 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handleTest(i);launchSpeechQA(i);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==100&&result==RESULT_OK&&data!=null){Uri uri=data.getData();submit(()->{manager.importUri(uri);manualPack=true;getPreferences(0).edit().putBoolean("manual_pack",true).apply();syncImportedModel();NativeBridge.release();message("模型已准备好 · 解码器："+manager.decoderLabel());},null);}}
 private void synthesize(String v,String s,String t,boolean stream,String runId)throws Exception{if(t.trim().isEmpty())throw new IOException("请输入文字");NativeBridge.ensureLoaded();ensureSelected();manager.requireCompatibleDecoder();File root=manager.current();if(!manager.ready(v)){message("正在准备所选模型…");root=manager.hasBundled()?manager.importBundled():downloadSelected(v);}if(!Arrays.asList("female","female_2","male","male_2").contains(s)||!new File(root,"voices/"+s+".f32").isFile())throw new IOException("该模型包未提供所选音色，请选择包内已有音色。");message("正在合成与缓冲 · 解码器："+manager.decoderLabel());File outputs=new File(getFilesDir(),"outputs");outputs.mkdirs();File out=new File(outputs,runId==null?Long.toString(System.currentTimeMillis()):runId);if(out.exists())throw new IOException("输出已存在");out.mkdirs();JSONObject report;
  try(StreamingPlayer player=new StreamingPlayer(stream,t.codePointCount(0,t.length()))){String ref=BuildConfig.DEBUG?getIntent().getStringExtra("qa_ref_path"):null;String refText=BuildConfig.DEBUG?getIntent().getStringExtra("qa_ref_text"):null;boolean icl=BuildConfig.DEBUG&&getIntent().getBooleanExtra("qa_icl",false);
   if(ref!=null&&!ref.isEmpty())ref=ModelManager.child(getFilesDir(),ref).getAbsolutePath();
   String result=(ref!=null&&!ref.isEmpty())?NativeBridge.runReference(root.getAbsolutePath(),v,s,t,4,20261029L,stream,player,out.getAbsolutePath(),ModelManager.acousticIdentity(root),ref,refText==null?"":refText,icl):NativeBridge.run(root.getAbsolutePath(),v,s,t,4,20261029L,stream,player,out.getAbsolutePath(),ModelManager.acousticIdentity(root));report=new JSONObject(result);player.drain();report.put("playback",player.metrics());}
  Files.write(new File(out,"report.json").toPath(),report.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));latest=new File(out,"sample.wav");getSharedPreferences("speech",MODE_PRIVATE).edit().putString("last_tts_audio",latest.getPath()).apply();message(String.format(Locale.ROOT,"合成完成 · %.2f 秒音频\n生成 RTF %.3f%s",report.getDouble("audio_s"),report.optDouble("generation_RTF",report.getDouble("RTF")),stream?String.format(Locale.ROOT," · 首块 %.0f ms",report.getDouble("first_pcm_ms")):""));if(!report.getString("EOS").equals("eos"))throw new IOException("生成未正常结束，结果已保留");
 }
 private void handleTest(Intent i){if(!BuildConfig.DEBUG||!i.getBooleanExtra("qa",false))return;String id=i.getStringExtra("qa_id");if(id==null||!id.matches("[a-zA-Z0-9_-]{1,80}"))return;String action=i.getStringExtra("qa_action");submit(()->{
   if(i.hasExtra("qa_cpu_module"))NativeBridge.cpuModuleForQA(i.getStringExtra("qa_cpu_module"));
   if("capabilities".equals(action)){NativeBridge.ensureLoaded();}
  else if("import".equals(action)){File zip=ModelManager.child(getFilesDir(),i.getStringExtra("zip"));manager.importZip(zip);manualPack=true;getPreferences(0).edit().putBoolean("manual_pack",true).apply();syncImportedModel();message("模型已准备好 · 解码器："+manager.decoderLabel());}
  else if("download".equals(action)){String address=i.getStringExtra("url");JSONObject entry=null;int selected=-1;for(int n=0;n<catalog.length();n++)if(address.equals(catalog.getJSONObject(n).getString("manifest_url"))){entry=catalog.getJSONObject(n);selected=n;}manager.download(address,i.getStringExtra("variant")==null?"P3":i.getStringExtra("variant"),entry);manualPack=entry==null;getPreferences(0).edit().putBoolean("manual_pack",manualPack).apply();final int index=selected;ui.post(()->{if(index>=0&&model.getSelectedItemPosition()!=index){skipModelSelection=true;model.setSelection(index);}url.setText(address);updateModelHint();});NativeBridge.release();message("模型已准备好 · 解码器："+manager.decoderLabel());}
  else if("bundled".equals(action)){manager.importBundled();NativeBridge.release();message("模型已准备好 · 解码器："+manager.decoderLabel());}
  else if("fetch".equals(action)){File f=new File(getFilesDir(),"qa-download-"+id);manager.downloadFile(i.getStringExtra("url"),i.hasExtra("download_urls")?new JSONArray(i.getStringExtra("download_urls")):null,f,i.getLongExtra("bytes",-1),i.getStringExtra("sha"),"下载测试");}
  else if("synth".equals(action)){synthesize(i.getStringExtra("variant"),i.getStringExtra("voice"),i.getStringExtra("text"),i.getBooleanExtra("stream",true),id);}
  else if("release".equals(action)){NativeBridge.release();}
  else throw new IOException("unknown QA action");
 },id);}
 @Override protected void onPause(){super.onPause();if(url!=null)getPreferences(0).edit().putString("manifest_url",url.getText().toString().trim()).apply();}
 @Override protected void onDestroy(){catalogWorker.shutdownNow();if(replay!=null)replay.release();super.onDestroy();}
}
